const allSeedPrompts: PromptSeedData[] = [
  ...seedPrompts,
  ...batch1Prompts,
  ...batch2Prompts,
  ...batch3Prompts,
  ...batch4Prompts,
  ...batch5Prompts,
  ...batch6Prompts,
];

export async function seedAiPrompts(): Promise<void> {
  try {
    const existing = await db.select({ slug: aiPrompts.slug }).from(aiPrompts);
    const existingSlugs = new Set(existing.map(e => e.slug));

    const newPrompts = allSeedPrompts.filter(p => !existingSlugs.has(p.slug));

    for (const p of newPrompts) {
      await db.insert(aiPrompts).values({
        slug: p.slug,
        title: p.title,
        promptText: p.promptText,
        audience: p.audience,
        category: p.category,
        tags: p.tags,
        useCase: p.useCase,
        safetyNote: p.safetyNote || null,
        iconName: p.iconName,
        isActive: true,
        version: 1,
      });
    }

    if (newPrompts.length > 0) {
      console.log(`Added ${newPrompts.length} new AI prompts (${existing.length + newPrompts.length} total, ${allSeedPrompts.length} defined).`);
    }

    const existingPrompts = allSeedPrompts.filter(p => existingSlugs.has(p.slug));
    let updatedCount = 0;
    for (const p of existingPrompts) {
      const result = await db.update(aiPrompts)
        .set({ promptText: p.promptText })
        .where(
          and(
            eq(aiPrompts.slug, p.slug),
            not(eq(aiPrompts.promptText, p.promptText))
          )
        );
      if (result.rowCount && result.rowCount > 0) {
        updatedCount++;
      }
    }

    if (updatedCount > 0) {
      console.log(`Updated promptText for ${updatedCount} existing AI prompts.`);
    }

    if (newPrompts.length === 0 && updatedCount === 0) {
      console.log(`AI prompts up to date (${existing.length} exist, ${allSeedPrompts.length} defined). No changes needed.`);
    }
  } catch (error) {
    console.error("Failed to seed AI prompts:", error);
  }
}
